using Curl.Api.Options.Http;

namespace Curl.Api.Stores;

[TestClass]
public sealed class CurlAltSvcStoreTests
{
    private const string Header =
        "# Your alt-svc cache. https://curl.se/docs/alt-svc.html\n# This file was generated by libcurl! Edit at your own risk.\n";

    private static readonly CurlAltSvcEntry H3 = new("h2", "example.com", 443, "h3", "alt.example.com", 8443, "20271231 00:00:00", Persist: false, Priority: 0);

    private DirectoryInfo _directory = null!;

    public TestContext TestContext { get; set; } = null!;

    [TestInitialize]
    public void CreateDirectory() => _directory = Directory.CreateTempSubdirectory("curl-api-altsvc-");

    [TestCleanup]
    public void DeleteDirectory() => _directory.Delete(recursive: true);

    private string PathOf(string name) => Path.Combine(_directory.FullName, name);

    [TestMethod]
    public void NewStore_UsesNoFile()
    {
        CurlAltSvcStore store = new();

        Assert.IsNull(store.FilePath);
        Assert.AreEqual(AltSvcControl.None, store.Control);
    }

    [TestMethod]
    public void Use_SetsTheFileAndControl()
    {
        CurlAltSvcStore store = new();

        store.Use("altsvc.txt", AltSvcControl.H2 | AltSvcControl.H3);

        Assert.AreEqual("altsvc.txt", store.FilePath);
        Assert.AreEqual(AltSvcControl.H2 | AltSvcControl.H3, store.Control);
    }

    [TestMethod]
    public void Use_EmptyPath_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => new CurlAltSvcStore().Use(string.Empty, AltSvcControl.H3));
    }

    [TestMethod]
    public async Task EveryFileMember_BeforeUse_ThrowsInvalidOperation()
    {
        CurlAltSvcStore store = new();
        CancellationToken token = TestContext.CancellationToken;

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => store.GetEntriesAsync(token));
        await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => store.AddAsync(H3, token));
        await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => store.ClearAsync(token));
        await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => store.LoadAsync(PathOf("in.txt"), token));
        await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => store.SaveAsync(PathOf("out.txt"), token));
    }

    [TestMethod]
    public async Task GetEntriesAsync_FileNotYetWritten_IsEmpty()
    {
        CurlAltSvcStore store = new();
        store.Use(PathOf("altsvc.txt"), AltSvcControl.H3);

        Assert.IsEmpty(await store.GetEntriesAsync(TestContext.CancellationToken));
    }

    [TestMethod]
    public async Task AddAsync_WritesTheEntryWithCurlsHeader()
    {
        CurlAltSvcStore store = new();
        store.Use(PathOf("altsvc.txt"), AltSvcControl.H3);

        await store.AddAsync(H3, TestContext.CancellationToken);

        Assert.AreEqual(
            Header + "h2 example.com 443 h3 alt.example.com 8443 \"20271231 00:00:00\" 0 0\n",
            await File.ReadAllTextAsync(PathOf("altsvc.txt"), TestContext.CancellationToken));
        CollectionAssert.AreEqual(new[] { H3 }, (await store.GetEntriesAsync(TestContext.CancellationToken)).ToArray());
    }

    [TestMethod]
    public async Task AddAsync_ReplacesOnlyTheSameOriginAndAlternativeProtocol()
    {
        CurlAltSvcStore store = new();
        store.Use(PathOf("altsvc.txt"), AltSvcControl.H3);
        CurlAltSvcEntry otherSourceAlpn = H3 with { SourceAlpn = "h1" };
        CurlAltSvcEntry otherHost = H3 with { SourceHost = "other.example" };
        CurlAltSvcEntry otherPort = H3 with { SourcePort = 80 };
        CurlAltSvcEntry otherDestinationAlpn = H3 with { DestinationAlpn = "h2" };
        CurlAltSvcEntry replacement = H3 with { SourceHost = "EXAMPLE.COM", DestinationPort = 9443, Persist = true };
        CancellationToken token = TestContext.CancellationToken;

        foreach (CurlAltSvcEntry entry in new[] { H3, otherSourceAlpn, otherHost, otherPort, otherDestinationAlpn, replacement })
        {
            await store.AddAsync(entry, token);
        }

        CollectionAssert.AreEqual(
            new[] { otherSourceAlpn, otherHost, otherPort, otherDestinationAlpn, replacement },
            (await store.GetEntriesAsync(token)).ToArray());
    }

    [TestMethod]
    public async Task AddAsync_Null_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(() => new CurlAltSvcStore().AddAsync(null!, TestContext.CancellationToken));
    }

    [TestMethod]
    public async Task ClearAsync_LeavesOnlyTheHeader()
    {
        CurlAltSvcStore store = new();
        store.Use(PathOf("altsvc.txt"), AltSvcControl.H3);
        await store.AddAsync(H3, TestContext.CancellationToken);

        await store.ClearAsync(TestContext.CancellationToken);

        Assert.AreEqual(Header, await File.ReadAllTextAsync(PathOf("altsvc.txt"), TestContext.CancellationToken));
    }

    [TestMethod]
    public async Task LoadAsync_ReplacesTheCacheWithTheWellFormedEntriesOfTheFile()
    {
        CurlAltSvcStore store = new();
        store.Use(PathOf("altsvc.txt"), AltSvcControl.H3);
        await store.AddAsync(H3 with { SourceHost = "old.example" }, TestContext.CancellationToken);
        await File.WriteAllTextAsync(PathOf("in.txt"), "# comment\n" + H3.ToFileLine() + "\nbroken line\n", TestContext.CancellationToken);

        await store.LoadAsync(PathOf("in.txt"), TestContext.CancellationToken);

        CollectionAssert.AreEqual(new[] { H3 }, (await store.GetEntriesAsync(TestContext.CancellationToken)).ToArray());
    }

    [TestMethod]
    public async Task SaveAsync_WritesTheCacheEntriesToAnotherFile()
    {
        CurlAltSvcStore store = new();
        store.Use(PathOf("altsvc.txt"), AltSvcControl.H3);
        await store.AddAsync(H3, TestContext.CancellationToken);

        await store.SaveAsync(PathOf("out.txt"), TestContext.CancellationToken);

        Assert.AreEqual(
            await File.ReadAllTextAsync(PathOf("altsvc.txt"), TestContext.CancellationToken),
            await File.ReadAllTextAsync(PathOf("out.txt"), TestContext.CancellationToken));
    }

    [TestMethod]
    public void ApplyTo_BeforeUse_LeavesTheOptions()
    {
        EasyHttpOptions http = new() { AltSvc = "mine.txt", AltSvcControl = AltSvcControl.H1 };

        Assert.AreSame(http, new CurlAltSvcStore().ApplyTo(http));
    }

    [TestMethod]
    public void ApplyTo_AfterUse_SetsTheFileAndControl()
    {
        CurlAltSvcStore store = new();
        store.Use("altsvc.txt", AltSvcControl.H2);

        EasyHttpOptions http = store.ApplyTo(new EasyHttpOptions());

        Assert.AreEqual("altsvc.txt", http.AltSvc);
        Assert.AreEqual(AltSvcControl.H2, http.AltSvcControl);
    }
}
